const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const K = nextInt();

    const A = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) {
        A[i] = nextInt();
    }

    // Ordena de forma decrescente (índices 1 a N)
    // Usamos subarray de 1 a N para ordenar
    const sub = A.subarray(1, N + 1);
    sub.sort((a, b) => b - a);

    // prev[i] armazena dp[i][j-1], curr[i] armazena dp[i][j]
    let prev = new Float64Array(N + 1);
    let curr = new Float64Array(N + 1);

    // Para j = 0, dp[i][0] = 0 para todo i, prev já está inicializado com 0.

    for (let j = 1; j <= K; j++) {
        curr.fill(Infinity);
        const minI = 3 * j;
        for (let i = minI; i <= N; i++) {
            let res = curr[i - 1];
            const diff = A[i - 1] - A[i];
            const cost = prev[i - 2] + diff * diff;
            if (cost < res) {
                res = cost;
            }
            curr[i] = res;
        }
        // Troca os buffers para a próxima iteração
        const temp = prev;
        prev = curr;
        curr = temp;
    }

    console.log(prev[N].toString());
}

solve();
